import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("Quote: base premiums and processing fee", () => {
    it("empty item list → premium 5 G (only the processing fee)", () => {
      const output = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [] }],
      });
      expect(output.results[0]).toEqual({ premium: 5 });
    });
    it("single sword, newcomer (0 years) → premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
      const output = runScenario({
        customer: { yearsWithMHPCO: 0 },
        steps: [{ op: "quote", items: [{ type: "sword" }] }],
      });
      expect(output.results[0]).toEqual({ premium: 115 });
    });
    it.todo("single amulet, newcomer → premium 71 G (60 base + 6 first insurance + 5 fee)");
    it.todo("single staff, newcomer → premium 93 G (80 base + 8 first insurance + 5 fee)");
    it.todo("single potion, newcomer → premium 49 G (40 base + 4 first insurance + 5 fee)");
    it.todo("single rune, newcomer → premium 33 G (25 base + 2.5 first insurance + 5 fee = 32.5, rounded up)");
  });

  describe("Component blocks of 3 alike components", () => {
    it.todo("2 runes → 50 G base premium (newcomer premium 60 G: 50 + 5 first insurance + 5 fee)");
    it.todo("3 runes → 60 G base premium, block applies (newcomer premium 71 G: 60 + 6 + 5)");
    it.todo("4 runes → 100 G base premium, no block — block requires exactly 3 (newcomer premium 115 G: 100 + 10 + 5)");
    it.todo("7 runes → 175 G base premium (newcomer premium 198 G: 175 + 17.5 + 5 = 197.5, rounded up in MHPCO's favor)");
    it.todo("2 runes + 1 moonstone → 75 G base premium, no block: different types (newcomer premium 88 G: 75 + 7.5 + 5 = 87.5, rounded up)");
    it.todo("3 runes + 3 moonstones → 120 G base premium, two separate blocks (newcomer premium 137 G: 120 + 12 + 5)");
  });

  describe("Premium modifiers", () => {
    it.todo("cursed surcharge applies to the cursed item's base premium only: cursed sword + plain amulet → 160 base + 50 curse + 16 first insurance + 5 fee = 231 G");
    it.todo("customer with exactly 2 years → loyalty discount applies: sword → 100 + 10 first − 20 loyalty + 5 fee = 95 G");
    it.todo("customer with 1 year → no loyalty discount: sword → 115 G");
    it.todo("sword with exactly enchantment 5 → high-enchantment surcharge: 100 + 30 + 10 + 5 = 145 G");
    it.todo("cursed sword with enchantment 5 → both surcharges: 100 + 50 + 30 + 10 + 5 = 195 G");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge: 115 G");
    it.todo("integration: newcomer with a cursed sword (steel, enchantment 3) → premium 165 G");
    it.todo("integration: 3-year customer's second quote, cursed sword enchantment 7 → premium 160 G (loyalty, first insurance and follow-up discount all apply)");
  });

  describe("Claim: standard reimbursement and deductible", () => {
    it.todo("regular steel sword (enchantment 3), damage 500 → payout 400 (full minus 100 deductible)");
    it.todo("damage to a rune, damage 200 → payout 100 (no special clause for components)");
    it.todo("deductible applies once per damaged item: sword 500 + amulet 300 in one incident → payout 600");
  });

  describe("Claim: special clauses (high enchantment vs. dragon material)", () => {
    it.todo("steel sword enchantment 9, damage 1000 → payout 400 (50 % clause, then deductible)");
    it.todo("dragon-material sword enchantment 5, damage 800 → payout 700 (full reimbursement, then deductible)");
    it.todo("dragon-material sword enchantment 9, damage 1000 → payout 400 (both clauses apply, 50 % rule wins)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 → payout 400 (threshold is ≥ 8)");
    it.todo("payout rounding down in MHPCO's favor: steel sword enchantment 9, damage 901 → 450.5 − 100 = 350.5 → payout 350");
  });

  describe("Claim: payout cap (twice the insurance sum)", () => {
    it.todo("sword insured (cap 2000): claim 1500 → payout 1400, remainingCap 600");
    it.todo("sword insured: two successive 1500 claims → second payout reduced to remaining cap 600, remainingCap 0");
    it.todo("sword + amulet → insurance sum 1600, cap 3200: sword damage 500 → payout 400, remainingCap 2800");
    it.todo("cursed sword → cap based on unmodified insurance value 1000 (cap 2000): damage 500 → payout 400, remainingCap 1600");
    it.todo("sword + 3 runes (block) → insurance sum 1750, cap 3500 (block discount affects premium only): sword damage 500 → payout 400, remainingCap 3100");
  });

  describe("Multiple items of the same type", () => {
    it.todo("policy with two swords → insurance sum 2000, cap 4000: both swords damaged 500 each → payout 800 (own deductible each), remainingCap 3200");
    it.todo("more damage entries of a type than insured (two sword damages, one sword) → whole claim rejected with an error");
  });

  describe("Scenario errors", () => {
    it.todo("quote with unknown item type (broomstick) → error, no results");
    it.todo("claim referencing an item not in the policy (amulet damaged, only sword insured) → error");
    it.todo("claim with negative damage amount (−200) → error");
  });

  describe("CLI", () => {
    it.todo("reads scenario JSON from stdin and writes results to stdout: 5-year customer, amulet quote (premium 59) then claim 200 (payout 100, remainingCap 1100)");
    it.todo("unknown item type → exits non-zero, writes error to stderr, no results on stdout");
  });
});

