export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: {
    cause: string;
    damages: Damage[];
  };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioOutput {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};

const roundUpInMHPCOsFavor = Math.ceil;

const quotePremium = (items: QuoteItem[]): number => {
  const basePremium = items.reduce(
    (sum, item) => sum + BASE_PREMIUMS[item.type],
    0,
  );
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_RATE;
  return roundUpInMHPCOsFavor(
    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  const quoteStep = scenario.steps[0] as QuoteStep;
  return { results: [{ premium: quotePremium(quoteStep.items) }] };
};

