export interface Customer {
  yearsWithMHPCO: number;
}

export interface QuoteItem {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface QuoteStep {
  op: "quote";
  items: QuoteItem[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: {
    cause: string;
    damages: Damage[];
  };
}

export type Step = QuoteStep | ClaimStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export type StepResult = QuoteResult | ClaimResult;

export interface ScenarioOutput {
  results: StepResult[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_RATE = 0.1;
const CURSE_SURCHARGE_RATE = 0.5;
const LOYALTY_MIN_YEARS = 2;
const LOYALTY_DISCOUNT_RATE = 0.2;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const roundUpInMHPCOsFavor = Math.ceil;

const basePremiumFor = (type: string, count: number): number => {
  const isComponentBlock =
    COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE;
  return isComponentBlock
    ? COMPONENT_BLOCK_PREMIUM
    : count * BASE_PREMIUMS[type];
};

const countItemsByType = (items: QuoteItem[]): Map<string, number> => {
  const countsByType = new Map<string, number>();
  for (const item of items) {
    countsByType.set(item.type, (countsByType.get(item.type) ?? 0) + 1);
  }
  return countsByType;
};

const quotePremium = (items: QuoteItem[], customer: Customer): number => {
  const basePremium = [...countItemsByType(items)].reduce(
    (total, [type, count]) => total + basePremiumFor(type, count),
    0,
  );
  const curseSurcharge = items.reduce(
    (total, item) =>
      total + (item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE : 0),
    0,
  );
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_RATE;
  const loyaltyDiscount =
    customer.yearsWithMHPCO >= LOYALTY_MIN_YEARS
      ? basePremium * LOYALTY_DISCOUNT_RATE
      : 0;
  return roundUpInMHPCOsFavor(
    basePremium +
      curseSurcharge +
      firstInsuranceSurcharge -
      loyaltyDiscount +
      PROCESSING_FEE,
  );
};

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  const quoteStep = scenario.steps[0] as QuoteStep;
  return {
    results: [{ premium: quotePremium(quoteStep.items, scenario.customer) }],
  };
};

